"""Exception hierarchy for the erp package."""


class ErpError(Exception):
    """Base class for all erp domain errors."""


class LedgerError(ErpError):
    """Raised when a posting would violate double-entry invariants."""


class OrderError(ErpError):
    """Raised for invalid orders (unknown SKU, bad quantity, ...)."""


class InvoiceError(ErpError):
    """Raised for invalid invoicing operations (e.g. duplicate invoice)."""


class PaymentError(ErpError):
    """Raised for invalid payments (overpay, non-positive amount, ...)."""

