"""SQLite schema and connection helper. Stdlib sqlite3, no ORM."""

import sqlite3

SCHEMA = """
CREATE TABLE IF NOT EXISTS products (
    sku          TEXT PRIMARY KEY,
    name         TEXT NOT NULL,
    price_cents  INTEGER NOT NULL CHECK (price_cents >= 0 AND typeof(price_cents) = 'integer')
);

CREATE TABLE IF NOT EXISTS orders (
    id          INTEGER PRIMARY KEY,
    customer    TEXT NOT NULL,
    created_at  TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS order_lines (
    id                INTEGER PRIMARY KEY,
    order_id          INTEGER NOT NULL REFERENCES orders(id),
    sku               TEXT NOT NULL REFERENCES products(sku),
    qty               INTEGER NOT NULL CHECK (qty > 0 AND typeof(qty) = 'integer'),
    unit_price_cents  INTEGER NOT NULL CHECK (unit_price_cents >= 0 AND typeof(unit_price_cents) = 'integer')
);

CREATE TABLE IF NOT EXISTS invoices (
    id           INTEGER PRIMARY KEY,
    order_id     INTEGER NOT NULL UNIQUE REFERENCES orders(id),
    total_cents  INTEGER NOT NULL CHECK (total_cents > 0 AND typeof(total_cents) = 'integer'),
    created_at   TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS payments (
    id           INTEGER PRIMARY KEY,
    invoice_id   INTEGER NOT NULL REFERENCES invoices(id),
    amount_cents INTEGER NOT NULL CHECK (amount_cents > 0 AND typeof(amount_cents) = 'integer'),
    created_at   TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS gl_entries (
    id           INTEGER PRIMARY KEY,
    batch_id     INTEGER NOT NULL,
    account      TEXT NOT NULL,
    debit_cents  INTEGER NOT NULL DEFAULT 0 CHECK (debit_cents >= 0 AND typeof(debit_cents) = 'integer'),
    credit_cents INTEGER NOT NULL DEFAULT 0 CHECK (credit_cents >= 0 AND typeof(credit_cents) = 'integer'),
    memo         TEXT NOT NULL DEFAULT ''
);

CREATE INDEX IF NOT EXISTS idx_gl_batch ON gl_entries(batch_id);
CREATE INDEX IF NOT EXISTS idx_gl_account ON gl_entries(account);
CREATE INDEX IF NOT EXISTS idx_payments_invoice ON payments(invoice_id);
CREATE INDEX IF NOT EXISTS idx_lines_order ON order_lines(order_id);
"""


def connect(path: str = ":memory:") -> sqlite3.Connection:
    """Open a database and make sure the schema exists."""
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    conn.executescript(SCHEMA)
    conn.commit()
    return conn


def check_cents(value: int, what: str) -> int:
    """Validate that value is a positive integer amount of cents."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{what} must be an integer number of cents, got {value!r}")
    if value <= 0:
        raise ValueError(f"{what} must be positive, got {value}")
    return value

